/* Original learning paths. Source links are references, not licensed media or model training. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;root.SVCurriculumData=api;})(typeof window!=='undefined'?window:globalThis,function(){
  'use strict';
  const L=(zh,en,ja,de)=>({zh,en,ja,de});
  const resources=[
    ['nicky-basics','With Nicky — Back to Basics','Nicola Benedetti · The Benedetti Foundation','en','https://www.benedettifoundation.org/with-nicky/v/back-to-basics',L('持琴的基础','Starting comfortably','構えの基礎','Bequem beginnen')],
    ['nicky-bow','With Nicky — Bow Holds Part 1','Nicola Benedetti · The Benedetti Foundation','en','https://www.benedettifoundation.org/with-nicky/v/yfk5mcnm6fkzgwhpb6x6pplxr2g349',L('放松握弓','A relaxed bow hold','力を抜いた弓の持ち方','Lockere Bogenhaltung')],
    ['nicky-left','With Nicky — Left Hand Part 1','Nicola Benedetti · The Benedetti Foundation','en','https://www.benedettifoundation.org/with-nicky/v/g47kkcmp3lcg4f8zst4xfx8xj4yg7c',L('认识左手','Getting to know the left hand','左手の使い方','Die linke Hand kennenlernen')],
    ['nicky-sound','With Nicky — Developing Your Sound','Nicola Benedetti · The Benedetti Foundation','en','https://www.benedettifoundation.org/with-nicky/v/989skccscjnlpblarapxk26dhjlwek',L('聆听你的音色','Listen to your tone','自分の音色を聴く','Dem eigenen Klang zuhören')],
    ['nicky-vibrato','With Nicky — Vibrato','Nicola Benedetti · The Benedetti Foundation','en','https://www.benedettifoundation.org/with-nicky/v/8b5k7et9dflzk2f6sgxc2n2x9653ly',L('揉弦观察','Watch vibrato','ビブラートを観察','Vibrato beobachten')],
    ['nicky-vibrato2','With Nicky — Vibrato Part 2','Nicola Benedetti · The Benedetti Foundation','en','https://www.benedettifoundation.org/with-nicky/v/vibrato-part-2',L('把揉弦放进音乐','Vibrato in music','音楽の中のビブラート','Vibrato in der Musik')],
    ['nicky-routine','Practice with Nicky — How to... Routine','Nicola Benedetti · The Benedetti Foundation','en','https://www.benedettifoundation.org/with-nicky/v/john-mcenroe-does-voice-over-now-zpk5h-7n8z9',L('一次只练一个目标','One practice goal at a time','一度に一つの練習目標','Jeweils ein Übungsziel')],
    ['yamaha-bowing','How to Play the Violin: Bowing','Yamaha · Chihiro Murakawa','en','https://www.yamaha.com/en/musical_instrument_guide/violin/play/play002.html',L('运弓基础','Bowing basics','運弓の基礎','Grundlagen der Bogenführung')],
    ['yamaha-fingers','How to Play the Violin: Fingering','Yamaha','en','https://www.yamaha.com/en/musical_instrument_guide/violin/play/play003.html',L('第一把位指法图解','First-position fingering','第1ポジションの運指','Griffe in der ersten Lage')],
    ['yamaha-setup-ja','バイオリン：構え方と弓の持ち方','Yamaha','ja','https://jp.yamaha.com/products/contents/strings/start/qanda/teacher/vstance/index.html',L('持琴与握弓图解（日文）','Posture and bow hold, in Japanese','構え方と弓の持ち方','Haltung und Bogengriff auf Japanisch')],
    ['trinity-arpeggio','Grade 2: Arpeggio Antics','Carl Fulbrook · Trinity College London','en','https://trinitycollege.com/qualifications/music/grade-exams/strings/resources/strings-technical-work/violin-grade-2-arpeggio-antics',L('琶音练习观摩','Observe an arpeggio study','アルペジオ練習の観察','Eine Arpeggioübung beobachten')],
    ['trinity-double','Grade 2: Double Trouble','Carl Fulbrook · Trinity College London','en','https://www.trinitycollege.com/qualifications/music/grade-exams/strings/resources/strings-technical-work/violin-grade-2-double-trouble',L('节奏与协调观摩','Rhythm and coordination','リズムと協調','Rhythmus und Koordination')],
    ['trinity-bow4','Grade 4: Bowing exercise','Carl Fulbrook · Trinity College London','en','https://www.trinitycollege.com/qualifications/music/grade-exams/strings/resources/strings-technical-work/violin-grade-4-bowing-exercise',L('分配你的弓段','Plan your bow use','弓の配分を考える','Den Bogen einteilen')],
    ['trinity-gwhizz','Grade 5: G-Whizz','Carl Fulbrook · Trinity College London','en','https://trinitycollege.com/qualifications/music/grade-exams/strings/resources/strings-technical-work/violin-grade-5-g-whizz',L('中级练习观摩','An intermediate study','中級練習の観察','Eine Übung für Fortgeschrittene')],
    ['trinity-swallows','Grade 5: Swallows Gliding','Carl Fulbrook · Trinity College London','en','https://www.trinitycollege.com/qualifications/music/grade-exams/strings/resources/strings-technical-work/violin-grade-5-swallows-gliding',L('双音与表现观摩','Double stops and expression','重音と表現の観察','Doppelgriffe und Ausdruck')],
    ['lounge-crossing','20 Tips to NOT Hit Other Strings','Zlata · Violin Lounge','en','https://www.violinlounge.com/20-tips-to-not-hit-other-strings-and-sound-scratchy-on-the-violin-violin-lounge-tv-377/',L('让换弦更清楚','Clearer string crossings','すっきりした移弦','Saubere Saitenwechsel')],
    ['lounge-legato','Legato Violin Bowing Technique','Zlata · Violin Lounge','en','https://www.violinlounge.com/blog/legato-violin-bowing-technique',L('连奏与乐句','Legato and phrasing','レガートとフレーズ','Legato und Phrasierung')],
    ['lounge-third','Violin Third Position','Zlata · Violin Lounge','en','https://www.violinlounge.com/blog/violin-third-position-all-notes-finger-chart-and-exercises',L('认识第三把位','Understand third position','第3ポジションを知る','Die dritte Lage verstehen')],
    ['lounge-spiccato','Spiccato Bowing on the Violin','Zlata · Violin Lounge','en','https://www.violinlounge.com/blog/spiccato-bowing-on-the-violin',L('跳弓的声音与动作','Spiccato sound and motion','スピッカートの音と動き','Klang und Bewegung beim Spiccato')],
    ['vengerov-masterclass','Exclusive violin masterclasses','Maxim Vengerov · Classic FM','en','https://www.classicfm.com/artists/maxim-vengerov/exclusive-violin-masterclass-videos/',L('向演奏家学习观察','Observe a concert violinist','演奏家の表現を観察','Einen Konzertgeiger beobachten')],
    ['abrsm-violin','Violin — Practical and Performance Grades','ABRSM','en','https://www.abrsm.org/en-mx/instruments/bowed-strings/violin?resources_categories_filter=Article',L('分级学习的能力范围','Skills across the grades','段階別に学ぶ能力','Fähigkeiten der einzelnen Stufen')],
    ['trinity-current','Violin repertoire · from 2025','Trinity College London','en','https://trinitycollege.com/qualifications/music/grade-exams/strings/repertoire-violin',L('现行分级资料入口','Current graded resources','現行の段階別資料','Aktuelle Prüfungsinformationen')]
  ].map(([id,title,author,language,url,topic])=>({id,title,author,language,url,topic,checkedAt:'2026-10-23',delivery:'external-link',permission:'link-only-no-media-license',historical:id.startsWith('trinity-')&&id!=='trinity-current'}));
  const steps=(watch,practice,review)=>[{id:'watch',text:watch},{id:'practice',text:practice},{id:'review',text:review}];
  const stages=[
    {id:'prepare',order:1,level:'zero',lessonId:'settle',resources:['nicky-basics','nicky-bow','yamaha-setup-ja'],title:L('先舒服地拿好琴','Find a comfortable start','楽な構えから始めよう','Bequem beginnen'),summary:L('今天只做一件事：找到放松的持琴和握弓感觉。','One goal today: find a relaxed hold for violin and bow.','今日の目標は一つ。楽な構えと弓の持ち方を探します。','Ein Ziel für heute: Geige und Bogen entspannt halten.'),steps:steps(L('打开原创示意，认识琴、弓与四根弦。','Open the original guide and find the violin, bow and four strings.','オリジナルの図で、バイオリン・弓・4本の弦を確認します。','Öffne die eigene Darstellung und finde Geige, Bogen und vier Saiten.'),L('先调音。短时间持琴，再放下休息；肩颈不要硬撑。','Tune first. Hold the violin briefly, then rest; keep shoulders and neck comfortable.','先に調弦します。短く構えて休み、肩や首に無理をかけません。','Stimme zuerst. Halte die Geige kurz und mache dann Pause; Schultern und Hals bleiben bequem.'),L('回想哪里紧绷；拿不稳或不舒服时请老师帮忙调整。','Notice any tension. Ask a teacher to adjust an unstable or uncomfortable setup.','力みを振り返ります。不安定または不快なら先生に調整してもらいましょう。','Achte auf Spannung. Lass eine unsichere oder unbequeme Haltung von einer Lehrkraft anpassen.')),tools:['tuner']},
    {id:'open-tone',order:2,level:'zero',lessonId:'open-strings',resources:['yamaha-bowing','nicky-sound'],title:L('让一根弦唱四拍','Let one string sing','1本の弦で4拍伸ばそう','Eine Saite singen lassen'),summary:L('先只拉 D 或 A 弦，听声音是否平稳。','Stay on D or A and listen for an even sound.','D線かA線だけを弾き、音が安定するか聴きます。','Bleibe auf D oder A und höre auf einen gleichmäßigen Ton.'),steps:steps(L('看空弦示范，留意上下弓方向。','Watch the open-string guide and notice the bow direction.','開放弦の手本で弓の方向を確認します。','Sieh dir die leere Saite an und beachte die Bogenrichtung.'),L('用 0.5× 慢速跟练四拍。停一下，放松，再拉四拍。','Follow at 0.5× for four beats. Pause, relax and repeat.','0.5×で4拍合わせます。止めて力を抜き、繰り返します。','Spiele bei 0,5× vier Schläge. Halte an, entspanne dich und wiederhole.'),L('录一小段回听：能否保持一个均匀的长音？','Record a short take: can you hear one even, sustained note?','短く録音し、一つの長い音が安定しているか聴きます。','Nimm kurz auf: Hörst du einen gleichmäßigen, gehaltenen Ton?')),tools:['metronome','studio']},
    {id:'fingers',order:3,level:'beginner',lessonId:'first-fingers',resources:['yamaha-fingers','nicky-left'],title:L('一个手指，一个目标音','One finger, one target note','指一本、目標の音一つ','Ein Finger, ein Zielton'),summary:L('从空弦与 1 指开始，再逐渐加入其他手指。','Begin with open string and finger 1, then add the other fingers.','開放弦と1の指から始め、少しずつ他の指を加えます。','Beginne mit leerer Saite und erstem Finger, dann ergänze die anderen.'),steps:steps(L('打开第一把位示范，先分清弦名与指号。','Open the first-position guide and distinguish string names from finger numbers.','第1ポジションの図で、弦名と指番号を区別します。','Öffne die erste Lage und unterscheide Saitennamen von Fingernummern.'),L('慢速逐音跟练；需要时手动开启麦克风，等待目标音。','Practise one note at a time. If useful, enable the microphone yourself to wait for the target note.','ゆっくり一音ずつ練習します。必要なら自分でマイクをオンにして音待ちを使います。','Übe Ton für Ton. Aktiviere bei Bedarf selbst das Mikrofon, um auf den Zielton zu warten.'),L('先用耳朵比较，再看单音音准参考。不要捏紧琴颈。','Compare by ear first, then check the single-note pitch reference. Avoid gripping the neck.','まず耳で比べ、その後で単音の音程表示を見ます。ネックを握り込みません。','Vergleiche zuerst nach Gehör, dann mit der Tonhöhenreferenz. Umklammere den Hals nicht.')),tools:['tuner','studio']},
    {id:'cross-strings',order:4,level:'beginner',lessonId:'crossing',resources:['lounge-crossing','trinity-arpeggio'],title:L('换一根弦，节奏继续','Change strings, keep the beat','弦を替えても拍を保とう','Saite wechseln, Takt halten'),summary:L('把换弦和落指分开练，再把两个动作接起来。','Practise crossing and fingering separately, then combine them.','移弦と運指を別々に練習してから合わせます。','Übe Saitenwechsel und Greifen getrennt und verbinde sie dann.'),steps:steps(L('看 D、A 弦切换，先不加左手手指。','Watch the move between D and A without adding left-hand fingers.','左手の指を使わず、D線とA線の移動を見ます。','Beobachte den Wechsel zwischen D und A ohne gegriffene Töne.'),L('慢练一个短段，用 A–B 循环重复两遍。','Practise a short section slowly and repeat twice with an A–B loop.','短い区間をゆっくり練習し、A–Bループで2回繰り返します。','Übe einen kurzen Abschnitt langsam und wiederhole zweimal mit A–B.'),L('回听换弦处有没有停顿；只记录一个下一次要改进的地方。','Listen for a pause at the crossing and note one thing to improve next time.','移弦のところで止まっていないか聴き、次に直す点を一つ記録します。','Höre auf Pausen beim Wechsel und merke dir eine Verbesserung fürs nächste Mal.')),tools:['metronome','studio']},
    {id:'first-phrase',order:5,level:'beginner',lessonId:'dawn-melody',resources:['nicky-routine','trinity-double','abrsm-violin'],title:L('把音符连成一句话','Make a little musical phrase','音を短いフレーズにしよう','Aus Tönen eine Phrase machen'),summary:L('用原创短句《晨光四弦》，先分句，最后连起来。','Use the original Four Strings at Dawn exercise: split it, then join it.','オリジナル曲「夜明けの四弦」を分けて練習し、最後につなげます。','Teile die Originalübung Vier Saiten im Morgenlicht und verbinde sie anschließend.'),steps:steps(L('先听一遍，找到你想练好的一个小句。','Listen once and choose one short phrase to work on.','一度聴き、練習したい短いフレーズを一つ選びます。','Höre einmal zu und wähle eine kurze Phrase zum Üben.'),L('慢速跟练，再静音自己拉；不要急着加速。','Follow slowly, then mute the guide and try on your own. Keep the pace comfortable.','ゆっくり合わせてから、手本を無音にして自分で弾きます。急いで速くしません。','Spiele langsam mit, schalte das Beispiel stumm und versuche es allein. Bleibe im angenehmen Tempo.'),L('录音回听：节拍、音高、乐句各选一项感受。进度由你自己确认。','Record and reflect on pulse, pitch and phrasing. You decide your own practice progress.','録音を聴き、拍・音程・フレーズを振り返ります。進み具合は自分で確認します。','Nimm auf und denke über Puls, Tonhöhe und Phrasierung nach. Du bestätigst deinen Fortschritt selbst.')),tools:['studio']},
    {id:'vibrato-study',order:6,level:'intermediate',lessonId:'vibrato',resources:['nicky-vibrato','nicky-vibrato2'],title:L('准备好了，再探索揉弦','Explore vibrato when ready','準備ができたらビブラート','Vibrato entdecken, wenn du bereit bist'),summary:L('选修：先稳定持琴、运弓与音准，再请老师确认准备度。','Optional: establish comfortable posture, bowing and intonation, then check readiness with a teacher.','任意です。構え・運弓・音程が安定してから、先生と準備を確認します。','Optional: Erst Haltung, Bogen und Intonation festigen, dann die Bereitschaft mit einer Lehrkraft prüfen.'),steps:steps(L('看轻柔揉弦图示，了解它只是动作参考。','Watch the gentle rocking illustration; it is a movement reference only.','ゆっくりした揺れの図を見ます。動きの参考であり、判定ではありません。','Sieh dir die sanfte Wiegebewegung an; sie dient nur als Bewegungshinweis.'),L('按老师建议做放松的慢练。紧张或疼痛时停止，不用揉弦掩盖音准。','Use relaxed, slow practice suggested by your teacher. Stop if tense or painful; do not hide intonation with vibrato.','先生の助言に沿って力を抜きゆっくり練習します。痛みや力みがあれば止め、音程をビブラートで隠しません。','Übe entspannt und langsam nach Rat deiner Lehrkraft. Bei Spannung oder Schmerzen stoppen; Vibrato verdeckt keine Intonationsprobleme.'),L('回听自己的长音；图示不评价揉弦质量，示范采样的揉弦不能独立调速。','Listen back to your sustained note. The illustration does not grade vibrato; the sample vibrato cannot be varied independently.','自分の長い音を聴きます。図はビブラートを採点せず、サンプル音の揺れだけを調速することもできません。','Höre deinen gehaltenen Ton an. Die Darstellung bewertet Vibrato nicht; das Sample-Vibrato ist nicht separat regelbar.')),tools:['studio']},
    {id:'position-and-bow',order:7,level:'intermediate',lessonId:null,resources:['lounge-third','lounge-legato','trinity-bow4','trinity-gwhizz'],title:L('认识换把与连奏','Explore shifting and legato','ポジション移動とレガート','Lagenwechsel und Legato verstehen'),summary:L('参考研习：跟着教师来源观察，带着问题练自己的熟悉短句。','Reference study: observe teacher sources and use your own familiar phrase.','参考学習です。先生の資料を観察し、弾き慣れたフレーズで考えます。','Referenzstudium: Beobachte Lehrquellen und arbeite mit einer vertrauten Phrase.'),steps:steps(L('打开下方来源，区分换把、换弦与连奏；本阶段没有高把位动画。','Open a source below and distinguish shifting, crossing and legato. This stage has no higher-position animation.','下の資料でポジション移動・移弦・レガートを区別します。高いポジションのアニメーションはありません。','Öffne unten eine Quelle und unterscheide Lagenwechsel, Saitenwechsel und Legato. Es gibt hier keine Animation höherer Lagen.'),L('只练老师已经教过的动作；用节拍器保持舒适速度，先明确起点与落点。','Practise only movements already taught by your teacher. Use a comfortable metronome pace and identify start and landing notes.','先生に教わった動きだけを練習します。楽なテンポで始点と着地点を確認します。','Übe nur bereits unterrichtete Bewegungen. Wähle ein angenehmes Metronomtempo und kläre Ausgangs- und Zielton.'),L('录下熟悉的短句，记录用弓是否顺畅，再向老师提一个具体问题。','Record a familiar phrase, note whether the bow feels smooth, and prepare one question for your teacher.','慣れたフレーズを録音し、弓が滑らかかを振り返り、先生への質問を一つ用意します。','Nimm eine vertraute Phrase auf, beobachte den Bogenfluss und formuliere eine Frage an deine Lehrkraft.')),tools:['metronome','studio']},
    {id:'expression',order:8,level:'advanced',lessonId:null,resources:['lounge-spiccato','vengerov-masterclass','trinity-swallows','trinity-current'],title:L('为音乐选择你的声音','Choose a sound for the music','音楽に合う音を選ぼう','Den passenden Klang wählen'),summary:L('进阶观摩：听音头、音色和乐句，形成自己的练习问题。','Advanced observation: listen to articulation, tone and phrasing, then shape your next practice question.','応用の観察です。音の立ち上がり・音色・フレーズを聴き、練習の問いを作ります。','Vertiefte Beobachtung: Höre auf Artikulation, Klang und Phrasierung und entwickle deine nächste Übungsfrage.'),steps:steps(L('在官方来源观看演奏家示范，比较一项声音特点；不必模仿所有高级动作。','Watch a performer at the official source and compare one sound quality; you need not copy every advanced movement.','公式資料で演奏家を見て、音の特徴を一つ比べます。高度な動きをすべて真似する必要はありません。','Sieh die Originalquelle an und vergleiche eine Klangeigenschaft; du musst nicht jede anspruchsvolle Bewegung nachahmen.'),L('用自己已经会的短句，尝试两种乐句表达。跳弓和多重音请由老师指导。','Use a phrase you already know and try two expressive intentions. Study spiccato and multiple stops with a teacher.','弾けるフレーズで二つの表現を試します。スピッカートや重音は先生と学びましょう。','Spiele eine bekannte Phrase mit zwei Ausdrucksideen. Spiccato und Mehrfachgriffe gehören in den Unterricht.'),L('保存两次录音并回听。记录你更喜欢哪一种，以及原因；这里没有专业自动评分。','Save two recordings and compare them. Note your preference and why; there is no professional automatic grading here.','2回録音して聴き比べます。好みと理由を記録します。専門的な自動採点はありません。','Speichere zwei Aufnahmen und vergleiche sie. Notiere deine Vorliebe und den Grund; es gibt hier keine professionelle automatische Bewertung.')),tools:['studio','tuner']}
  ];
  function freeze(v){Object.values(v).forEach(x=>{if(x&&typeof x==='object')freeze(x);});return Object.freeze(v);}
  return freeze({schema:1,revision:'20261023-v22',checkedAt:'2026-10-23',stages,resources});
});
